{
  "description": "The creature is a quadrupedal mammal shown in right-facing profile walking, with the overall size, shape, fur and head of a brown bear but with beetle-like structures integrated into its body. Its entire body except for the back is covered in dense, shaggy brown fur that is lighter tan on the muzzle and on the chest and belly, with a short furry tail at the rear and four thick legs ending in clawed paws. A single long, glossy, dark brown, sickle-shaped horn curves up and back from the middle of its forehead, and its dorsal side from the shoulders to the rump is covered by two large, smooth, domed, glossy dark brown hard shell plates. Along both flanks just below the edges of the shell there are rows of small, dark, oval holes in the fur.",
  "parts": [
    {
      "part": "head",
      "looks_like": "bear-like with an elongated snout, black nose, small brown eyes, light tan fur on the muzzle, whiskers, and a slightly open mouth",
      "where": "at the front end of the body, facing to the right"
    },
    {
      "part": "horns",
      "looks_like": "one long, glossy dark brown, sharply curved horn like a rhinoceros beetle horn, tapering to a point, with a small tooth-like projection on the inner curve and fine serrations along the lower inner edge near the base",
      "where": "emerging from the center of the forehead on top of the head and curving upward and backward"
    },
    {
      "part": "ears",
      "looks_like": "two small, rounded, densely furry brown ears",
      "where": "on top of the head behind the base of the horn"
    },
    {
      "part": "mane",
      "looks_like": "thick, shaggy, layered brown fur forming a ruff",
      "where": "around the neck, throat and chest"
    },
    {
      "part": "legs",
      "looks_like": "four thick, heavily furred, muscular brown legs with shaggy hair",
      "where": "two forelegs under the chest and two hindlegs under the hips, supporting the body"
    },
    {
      "part": "feet",
      "looks_like": "four large broad paws with blunt dark claws visible on the toes",
      "where": "at the bottom ends of each leg on the ground"
    },
    {
      "part": "tail",
      "looks_like": "small, short, furry brown stump",
      "where": "at the rear end of the body above the hindlegs"
    },
    {
      "part": "shell",
      "looks_like": "large, glossy, hard, dark brown beetle-like exoskeleton with a smooth domed surface, longitudinal ridges on the rear section and cracked texture near the lower edges",
      "where": "covering the entire dorsal side from just behind the neck to the rump"
    },
    {
      "part": "plates",
      "looks_like": "two separate glossy plates: a smaller anterior pronotum-like plate over the shoulders and a larger oval elytra-like plate over the back and rump, both dark brown with black rims",
      "where": "on the back, the anterior plate sits over the shoulder area and the posterior plate sits over the mid-back to rump, with a narrow gap between them"
    },
    {
      "part": "markings",
      "looks_like": "lighter cream-tan fur on the muzzle and on the lower chest and belly contrasting with darker brown fur elsewhere, and two rows of small dark oval holes (spiracles) in the fur",
      "where": "light fur on the face and ventral side; rows of holes along the left flank below the shell edges, six to seven holes under the posterior plate and four holes under the anterior plate"
    }
  ],
  "attached_objects": [],
  "animals": [
    "bear",
    "beetle"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
